body.content:
:::step{purpose="学会打开控制台是所有前端调试的第一步。红色错误信息不是惩罚，而是路标——就像调音器告诉你哪根弦不准，它精确地指出错误类型和位置。" expected="控制台出现红色错误信息，包含错误类型（ReferenceError/TypeError）、文件名和行号。"}
打开浏览器控制台（F12），查看红色错误信息——第一条错误告诉你第几行出了什么错？
:::

:::step{purpose="ReferenceError 是最常见的错误类型——{{term:变量}}未定义。学会从错误信息中的行号定位代码，而不是盲目猜测，能大幅缩短调试时间。" expected="修复后再次运行，第一条红色错误消失，第二条错误出现——就像调音时修好一根弦后，下一根弦的问题才被听到。"}
根据第一条错误提示（{{term:document}} 拼写为 docuement），找到对应代码行并修复
:::

:::step{purpose="错误之间会互相掩盖——一个错误导致后续代码不执行。这就像交响乐中一个声部漏了，后面的乐手没法跟进去。逐个修复错音，直到所有声部和谐共鸣。" expected="控制台变干净（无红色错误），点击收藏按钮后卡片状态正常切换，消息文字正确显示。"}
继续修复剩余 4 个错误：{{term:querySelector}} 大小写 → {{term:变量}}名不一致 → {{term:textContent}} 拼写错误 → {{term:innerHTML}} 大小写
:::

starter.css:
h1 {
  text-align: center;
  color: #8B2E2E;
}
#card {
  background: #FFFAF2;
  border: 2px solid #D4C5A9;
  border-radius: 12px;
  padding: 24px;
  text-align: center;
  max-width: 360px;
  margin: 0 auto;
}
.card-title {
  color: #8B2E2E;
  margin-bottom: 8px;
}
.card-desc {
  color: #6B5A4E;
  margin-bottom: 16px;
}
#likeBtn {
  background: #8B2E2E;
  color: white;
  border: none;
  padding: 10px 28px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 15px;
}
#likeBtn:hover {
  background: #C94545;
}
#msg {
  text-align: center;
  color: #C9A96E;
  margin-top: 16px;
  font-weight: 600;
}

starter.js:
// 👋 欢迎来到调试训练！
// 这个页面有 5 个故意埋下的错误。打开控制台（F12），然后逐个修复它们。
// 注意：每次只能看到一个错误——修好一个、刷新页面，下一个才会出现！
console.log("🎻 调试训练开始！打开 F12 控制台，红色错误就是你要修复的 bug");
console.log("提示：每修好一个错误就点‘运行’按钮，看下一个错误是什么");
// 错误1：document 拼写错误 
let title = docuement.querySelector(".card-title");
// 错误2：querySelector 大小写错误（修好上面那个才能看到这个）
let likeBtn = document.queryselector("#likeBtn");
// 错误3：变量名不一致——声明的是 likeBtn，用的却是 fixBtn
let msg = document.querySelector("#msg");
fixBtn.addEventListener("click", function() {
  if (likeBtn.textContent === "❤ 收藏") {
    likeBtn.textContent = "❤ 已收藏";
    likeBtn.style.background = "#C9A96E";
    // 错误4：textContent 拼写错误（这行不会在控制台报错，但消息不会更新！）
    msg.textContet = "已添加到你的收藏！";
  } else {
    likeBtn.textContent = "❤ 收藏";
    likeBtn.style.background = "#8B2E2E";
    // 错误5：innerHTML 大小写错误（同样不会报错，但功能不生效）
    msg.innerhtml = "已取消收藏";
  }
});
